        root: root.to_path_buf(),
        changesets_dir,
        cascade: CascadeConfig {
            mode,
            bump_severity,
            peer_escalation,
            preserve_npm_ranges,
        },
        validation: ValidationConfig { allow_empty_changesets },
        changelog_layout,
        product_release,
        registries,
        packages,
        package_sets,
        groups: GroupTable::default(),
        raw_groups,
        provenance,
